"""Draft I/O against projects generated by pyCapCut (an independent CapCut draft library)."""

import json
import os

import numpy as np
import pytest

pycapcut = pytest.importorskip("pycapcut")

from smart_tracking import capcut_draft as cd
from smart_tracking.camera import compute_camera, settings_for_mode
from smart_tracking.capcut_transform import ClipGeometry, video_to_canvas
from smart_tracking.keyframes import KF_POS_X, KF_POS_Y, KF_SCALE_X, build_keyframes
from smart_tracking.tracking import ObjectTracker, TrackData
from smart_tracking.video_io import FrameSource
from tests.synth import make_video


@pytest.fixture()
def project(tmp_path):
    video = str(tmp_path / "media" / "phone.mp4")
    gts = make_video(video, n=120, w=960, h=540)
    root = tmp_path / "drafts"
    root.mkdir()
    folder = pycapcut.DraftFolder(str(root))
    script = folder.create_draft("Demo", 1920, 1080, allow_replace=True)
    script.add_track(pycapcut.TrackType.video)
    seg = pycapcut.VideoSegment(video, pycapcut.trange("0s", "3s"),
                                source_timerange=pycapcut.trange("0.5s", "3s"))
    # reference keyframe written by pyCapCut itself, used to compare the JSON shape
    seg.add_keyframe(pycapcut.KeyframeProperty.alpha, "0s", 1.0)
    script.add_segment(seg)
    script.save()
    return str(root / "Demo"), video, gts, str(root)


def test_list_and_read_project(project):
    path, video, _, root = project
    projs = cd.list_projects(root)
    assert [p.path for p in projs] == [os.path.normpath(path)]
    d = cd.DraftProject(path)
    assert d.canvas_size == (1920, 1080)
    segs = d.video_segments()
    assert len(segs) == 1
    s = segs[0]
    assert os.path.normpath(s.material_path) == os.path.normpath(video) and s.file_exists
    assert s.source_start == 500_000 and s.source_duration == 3_000_000 and s.speed == pytest.approx(1.0)


def test_apply_keyframes_writes_capcut_structure(project, tmp_path):
    path, video, gts, _ = project
    d = cd.DraftProject(path)
    seg = d.video_segments()[0]
    src = FrameSource(video)
    first = src.time_to_frame(seg.source_start / 1e6)
    count = src.time_to_frame(seg.source_duration / 1e6)
    track = TrackData(first, count, src.width, src.height, src.fps)
    ObjectTracker().track(src, track, first, gts[first][:4])
    geo = ClipGeometry(src.width, src.height, *d.canvas_size)
    settings = settings_for_mode("smooth")
    settings.keep_filled = False  # allow full centering so framing can be asserted below
    cam = compute_camera(track, geo, settings)
    ks = build_keyframes(cam, geo, src.fps, seg.speed)
    res = d.apply_keyframes(seg.segment_id, ks, str(tmp_path / "backups"))
    assert os.path.isdir(res["backup"])

    with open(d.timeline_file, encoding="utf-8") as f:
        content = json.load(f)
    s = d.find_segment(content, seg.segment_id)
    by_prop = {k["property_type"]: k for k in s["common_keyframes"]}
    # untouched foreign keyframes survive
    assert "KFTypeAlpha" in by_prop
    ref = by_prop["KFTypeAlpha"]
    for prop in (KF_POS_X, KF_POS_Y, KF_SCALE_X):
        kl = by_prop[prop]
        assert set(kl) == set(ref)                                   # same fields as pyCapCut
        assert set(kl["keyframe_list"][0]) == set(ref["keyframe_list"][0])
        offs = [k["time_offset"] for k in kl["keyframe_list"]]
        assert offs == sorted(offs) and offs[0] == 0 and offs[-1] <= seg.target_duration
    assert s["uniform_scale"]["on"] is True
    assert s["clip"]["scale"]["x"] == pytest.approx(ks.values[KF_SCALE_X][0])

    # simulate CapCut's linear keyframe interpolation and check the object stays framed
    t_us = np.array(ks.offsets_us)
    vals = {p: np.array([k["values"][0] for k in by_prop[p]["keyframe_list"]]) for p in (KF_POS_X, KF_POS_Y, KF_SCALE_X)}
    errs, drift = [], []
    for i in range(20, track.count):
        tt = i / src.fps * 1e6
        sc, px, py = (np.interp(tt, t_us, vals[p]) for p in (KF_SCALE_X, KF_POS_X, KF_POS_Y))
        m = video_to_canvas(geo, sc, px, py, 0)
        x, y, w, h, _ = gts[first + i]
        c = m[:, :2] @ (x + w / 2, y + h / 2) + m[:, 2]
        errs.append(np.hypot(c[0] - 960, c[1] - 540))
        dense = video_to_canvas(geo, cam.scale[i], cam.pos_x[i], cam.pos_y[i], 0)
        drift.append(np.hypot(*(c - (dense[:, :2] @ (x + w / 2, y + h / 2) + dense[:, 2]))))
    assert np.median(errs) < 120      # object stays near the center (same bound as Smooth in test_camera)
    assert max(drift) < 3             # keyframes reproduce the dense camera path


def test_reapply_replaces_instead_of_duplicating(project, tmp_path):
    path, *_ = project
    d = cd.DraftProject(path)
    seg = d.video_segments()[0]
    from smart_tracking.keyframes import KeyframeSet
    ks = KeyframeSet([0, 10], [0, 333_333], {KF_POS_X: [0, 0.1], KF_POS_Y: [0, 0.2], KF_SCALE_X: [1, 1.5]}, 11)
    for _ in range(3):
        d = cd.DraftProject(path)
        d.apply_keyframes(seg.segment_id, ks, str(tmp_path / "b"))
    d = cd.DraftProject(path)
    s = d.find_segment(d.content, seg.segment_id)
    props = [k["property_type"] for k in s["common_keyframes"]]
    assert props.count(KF_POS_X) == 1 and props.count(KF_SCALE_X) == 1


def test_backup_and_restore(project, tmp_path):
    path, *_ = project
    d = cd.DraftProject(path)
    with open(d.timeline_file, "rb") as f:
        original = f.read()
    seg = d.video_segments()[0]
    from smart_tracking.keyframes import KeyframeSet
    ks = KeyframeSet([0], [0], {KF_POS_X: [0.3], KF_POS_Y: [0.0], KF_SCALE_X: [2.0]}, 1)
    broot = str(tmp_path / "b")
    res = d.apply_keyframes(seg.segment_id, ks, broot)
    assert open(d.timeline_file, "rb").read() != original
    assert cd.list_backups(broot, d.name)[0] == res["backup"]
    cd.restore_backup(res["backup"], path)
    assert open(d.timeline_file, "rb").read() == original


def test_remove_tracking_keyframes(project, tmp_path):
    path, *_ = project
    d = cd.DraftProject(path)
    seg = d.video_segments()[0]
    from smart_tracking.keyframes import KeyframeSet
    ks = KeyframeSet([0], [0], {KF_POS_X: [0.3], KF_POS_Y: [0.0], KF_SCALE_X: [2.0]}, 1)
    d.apply_keyframes(seg.segment_id, ks, str(tmp_path / "b"))
    d = cd.DraftProject(path)
    d.remove_tracking_keyframes(seg.segment_id, str(tmp_path / "b"))
    d = cd.DraftProject(path)
    props = {k["property_type"] for k in d.find_segment(d.content, seg.segment_id)["common_keyframes"]}
    assert props == {"KFTypeAlpha"}


def test_sidecar_timeline_copies_are_synced(project, tmp_path):
    path, *_ = project
    d = cd.DraftProject(path)
    tl = os.path.join(path, "Timelines", "ABC")
    os.makedirs(tl)
    with open(os.path.join(tl, "draft_content.json"), "w", encoding="utf-8") as f:
        json.dump(d.content, f)
    with open(os.path.join(path, "draft_info.json"), "wb") as f:
        f.write(os.urandom(256))  # an encrypted sidecar must be left alone
    seg = d.video_segments()[0]
    from smart_tracking.keyframes import KeyframeSet
    ks = KeyframeSet([0], [0], {KF_POS_X: [0.3], KF_POS_Y: [0.0], KF_SCALE_X: [2.0]}, 1)
    res = d.apply_keyframes(seg.segment_id, ks, str(tmp_path / "b"))
    assert len(res["files"]) == 2
    copy = json.load(open(os.path.join(tl, "draft_content.json"), encoding="utf-8"))
    assert any(k["property_type"] == KF_SCALE_X for k in d.find_segment(copy, seg.segment_id)["common_keyframes"])


def test_encrypted_timeline_is_refused(tmp_path):
    p = tmp_path / "Enc"
    p.mkdir()
    (p / "draft_content.json").write_bytes(b"\x8f\x02\xa1" + os.urandom(500))
    with pytest.raises(cd.EncryptedDraftError):
        cd.DraftProject(str(p))


def test_placeholder_paths_resolve(project):
    path, video, *_ = project
    d = cd.DraftProject(path)
    mat = d.content["materials"]["videos"][0]
    mat["path"] = "##_draftpath_placeholder_0E685133-18CE-45ED-8CB8-2904A212EC80_##/media/x.mp4"
    s = d.video_segments()[0]
    assert os.path.normpath(s.material_path) == os.path.normpath(os.path.join(path, "media", "x.mp4"))
